'use strict';
const $=(s,p=document)=>p.querySelector(s),root=$('#root');
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',chat:'M21 11a8 8 0 0 1-8 8H7l-5 3V11a9 9 0 0 1 19 0Z M7 9h9 M7 13h6',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3z M12 6v16',code:'m8 6-6 6 6 6 m8-12 6 6-6 6 m-3-15-2 18',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z m-5 10 3 3 7-7',card:'M2 5h20v14H2z M2 9h20 M6 15h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',arrow:'M5 12h14 m-5-5 5 5-5 5',external:'M14 3h7v7 M21 3 10 14 M10 3H3v18h18v-7',check:'m4 12 5 5L20 6',plus:'M12 4v16 M4 12h16',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M4 22v-3a8 8 0 0 1 16 0v3',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v6l4 2',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 12h8 M8 16h8',globe:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M3 12h18 M12 3c-5 6-5 12 0 18 5-6 5-12 0-18',logout:'M9 3H3v18h6 M10 12h11 m-4-4 4 4-4 4',refresh:'M20 7a9 9 0 1 0 1 8 M20 2v6h-6',menu:'M3 6h18 M3 12h18 M3 18h18',copy:'M8 8h13v13H8z M16 8V3H3v13h5',download:'M12 2v13 m-5-5 5 5 5-5 M4 17v5h16v-5',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.chat}"/></svg>`;
const esc=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S={page:'landing',demo:false,token:null,email:'',config:null,business:null,sources:[],conversations:[],selected:null,filter:'all',search:'',platform:'website',usage:null,authMode:'login',deliveryDestination:'',resendUntil:0,busy:false,sourceKind:'text',replyDraft:''};
const statusText=c=>c.status==='closed'?'Closed':c.mode==='waiting'?'Needs a person':c.mode==='human'?'With your team':'AI assistant';
const pill=c=>`<span class="pill ${c.status==='closed'?'closed':c.mode==='waiting'?'waiting':c.mode==='human'?'human':''}"><span class="dot"></span>${esc(statusText(c))}</span>`;
const plans={starter:{name:'Starter',price:19,description:'A clear beginning for independent businesses.',features:['1 website origin','250 AI replies / month','10 approved knowledge sources','Web, iOS, Android & API installation','Human handoff & transcript export']},growth:{name:'Growth',price:49,description:'More answers, across more of your business.',features:['3 website origins','1,000 AI replies / month','20 approved knowledge sources','Everything in Starter','Custom widget branding']},scale:{name:'Scale',price:99,description:'Room for a larger knowledge library.',features:['5 website origins','3,000 AI replies / month','50 approved knowledge sources','Everything in Growth','90-day conversation history']}};
function initials(s){return(s||'OP').split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();}
function brand(){return '<a class="brand" href="/" data-action="home"><img src="/favicon.svg" alt="">OrderProof</a>';}
function publicNav(){return `<nav class="publicnav" aria-label="Main navigation">${brand()}<div class="publiclinks"><a class="desktop" href="/review">Reviewer guide</a><a class="desktop" href="/#how">How it works</a><button class="link desktop" data-action="public-integrations">Integrations</button><button class="link desktop" data-action="public-plans">Pricing</button><button class="link" data-action="login">Sign in</button><button class="btn" data-action="register">Start free trial ${icon('arrow')}</button></div></nav>`;}
function footer(){return '<footer class="footer"><span>OrderProof · Support, with a record.</span><span><a href="/privacy" data-action="privacy">Privacy & retention</a> · Powered by AWS</span></footer>';}
function toast(message){const e=$('#toast');e.textContent=message;e.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.style.display='none',6500);}
function error(e){const d=$('#modal[open] #form-error')||$('#form-error');if(d){d.textContent=e.message||String(e);d.classList.remove('hidden');d.focus();}else toast(e.message||String(e));}
function modal(html,cls=''){const d=$('#modal');d.className=cls;d.innerHTML=html;d.showModal();}
function closeModal(){$('#modal').close();}
function mhead(title){return `<div class="modalhead"><h2>${title}</h2><button class="close" data-action="close-modal" aria-label="Close dialog">×</button></div>`;}
function go(page){S.page=page;render();window.scrollTo(0,0);}
function trialDays(){return Math.max(0,Math.ceil(((Math.max(S.business?.trialEnds||0,S.business?.reviewAccessUntil||0)||Date.now()/1000+604800)-Date.now()/1000)/86400));}
function landing(){return `${publicNav()}<main id="main"><section class="hero"><div><div class="eyebrow">Every conversation deserves a clear record</div><h1>Helpful answers.<br>Human connection.<br><em>Nothing lost.</em></h1><p>AI support grounded in your business. A smooth handoff to your team. One preserved conversation, from the first hello to the final agreement.</p><div class="actions"><button class="btn" data-action="register">Start your 7-day free trial ${icon('arrow')}</button><button class="btn secondary" data-action="demo">Explore the demo</button></div><p class="footnote">No credit card required. The demo uses fictional data and prepared answers, not live AI.</p></div><div class="hero-scene"><div class="scene-window"><div class="scene-top"><span class="scene-logo">${icon('chat')}</span><div>Evergreen Studio<small class="tiny muted"><br>Support that stays with you</small></div><span class="pill">Example</span></div><div class="scene-messages"><div class="bubble customer">Can I return an unused item after 10 days?</div><div class="bubble ai"><div class="scene-agent">AI assistant</div>Yes. Our policy allows returns of unused items within 14 days. Would you like help with the next step?<div class="scene-cite">↳ Source: Returns & exchanges</div></div><div class="bubble customer">Yes, could I speak with someone?</div><div class="scene-note">${icon('user')} A human picks up with the full conversation.</div><div class="bubble ai"><div class="scene-agent">Alex · Support team</div>Hi! I can help. You won’t need to explain it again.</div></div><div class="scene-bottom"><span>${icon('shield')} One conversation. A preserved record.</span><span>Illustrative sample</span></div></div></div></section><div class="truststrip"><span>${icon('book')} Answers from your knowledge</span><span>${icon('user')} Human handoff, same conversation</span><span>${icon('shield')} Verifiable conversation history</span></div><section class="section" id="how"><div class="sectionhead"><div class="eyebrow">Thoughtful support, from beginning to end<h2>One connected experience.<br>For both sides of the chat.</h2></div><p>Give your customers a helpful first answer—and your team the context to finish the conversation.</p></div><div class="features"><article class="feature">${icon('book')}<h3>Bring what your business knows</h3><p>Add policies, documents, and public website pages. Review and approve the sources your assistant can use.</p></article><article class="feature">${icon('chat')}<h3>Be there when it matters</h3><p>Let AI answer routine questions. When a person is needed, pick up in the inbox with the complete history.</p></article><article class="feature">${icon('shield')}<h3>Keep what was actually said</h3><p>Messages are append-only. Verify and export the timeline, with protected archives when conversations close.</p></article></div><div class="callout good"><span>One installation, wherever your customers are: websites, web apps, iOS, Android, or a standalone support page.</span><button class="link" data-action="public-integrations">See integrations →</button></div></section></main>${footer()}`;}
function demoData(){const time=new Date().toISOString();S.demo=true;S.business={name:'Evergreen Studio',website:'https://evergreen.example',domains:['https://evergreen.example'],siteId:'demo',greeting:'Hi there! Welcome to Evergreen Studio. How can we help?',agentName:'Alex',description:'Thoughtfully made home essentials.',color:'#245e4c',plan:'trial',trialEnds:Date.now()/1000+604800,version:1};S.sources=[{id:'s1',title:'Returns & exchanges',kind:'text',approved:true,content:'We accept returns of unused products in their original packaging within 14 days of delivery. Contact our support team with your order number to request a return. Refunds are processed after inspection.',createdAt:time,url:''},{id:'s2',title:'Shipping & delivery',kind:'text',approved:true,content:'Standard delivery takes 3–5 business days. Orders over $75 qualify for free standard shipping. Express delivery is not currently available.',createdAt:time,url:''},{id:'s3',title:'About Evergreen',kind:'text',approved:false,content:'Evergreen Studio makes thoughtful home essentials. Our support team is available Monday through Friday, 9 AM to 5 PM.',createdAt:time,url:''}];const msg=(role,content,seq,sources=[])=>({role,content,sequence:seq,at:time,sources});S.conversations=[{id:'demo-1',name:'Maya Chen',category:'returns',mode:'waiting',status:'waiting',createdAt:time,updatedAt:time,seq:4,preview:'Could someone help me start the return?',messages:[msg('system','Conversation started. The visitor agreed to a recorded support conversation.',1),msg('customer','Can I return an unused item after 10 days?',2),msg('assistant','Yes. Our approved policy allows returns of unused products in their original packaging within 14 days of delivery.',3,[{title:'Returns & exchanges',excerpt:'We accept returns of unused products in their original packaging within 14 days of delivery.'}]),msg('system','The customer requested a human. Waiting for the support team.',4)]},{id:'demo-2',name:'Jordan Lee',category:'orders',mode:'ai',status:'open',seq:2,createdAt:time,updatedAt:time,preview:'How long does standard delivery take?',messages:[msg('customer','How long does standard delivery take?',1),msg('assistant','Standard delivery takes 3–5 business days, according to the Shipping & delivery policy.',2,[{title:'Shipping & delivery',excerpt:'Standard delivery takes 3–5 business days.'}])]},{id:'demo-3',name:'Sam Rivera',category:'general',mode:'human',status:'closed',seq:3,createdAt:time,updatedAt:time,preview:'Thank you—that answers my question.',archive:{demo:true},messages:[msg('customer','Can I get help with a product question?',1),msg('agent','Of course. We’re happy to help.',2),msg('system','Sample conversation closed. No real archive has been created.',3)]}];S.usage={plan:'trial',aiUsed:2,aiLimit:100,trialEnds:S.business.trialEnds,sourceLimit:20,billingEnabled:false};S.selected=S.conversations[0];S.filter='all';go('overview');}
const navItems=[['overview','grid','Overview'],['inbox','chat','Inbox'],['knowledge','book','Knowledge'],['install','code','Install & connect'],['records','shield','Conversation records'],['plans','card','Plans & usage'],['settings','settings','Settings']];
function shell(content){const review=S.business?.reviewAccessUntil>Date.now()/1000?`<div class="callout good" role="status">Reviewer access through ${esc(new Date(S.business.reviewAccessUntil*1000).toLocaleDateString())}. Usage limits still apply; no paid subscription is active.</div>`:'';const demoNotice=S.demo?'<div class="callout warn" role="note">Fictional walkthrough · prepared answers, no Bedrock calls, no live support team, and no protected archive. <a href="/review">See how to verify the real workflow.</a></div>':'';content=review+demoNotice+content;return `<div class="shell"><aside class="sidebar">${brand()}<button class="company-select" data-action="settings"><span class="avatar">${esc(initials(S.business?.name||'Your business'))}</span><span><strong>${esc(S.business?.name||'Your workspace')}</strong><small>${S.demo?'Sample business':'Business workspace'}</small></span></button><div class="navgroup">WORKSPACE</div>${navItems.map(([id,i,title],idx)=>`${idx===5?'<div class="navgap"></div><div class="navgroup">MANAGE</div>':''}<button class="sideitem ${S.page===id?'active':''}" data-action="${id}">${icon(i)}${title}${id==='inbox'?`<span class="badgecount">${S.conversations.filter(c=>c.mode==='waiting'&&c.status!=='closed').length}</span>`:''}</button>`).join('')}<div class="sidebar-bottom"><div class="trial-card"><strong>${S.demo?'Explore the full picture':`${trialDays()} days left in your trial`}</strong><p>${S.demo?'Sample data. Try the inbox, knowledge setup, and widget.':'Your workspace, your knowledge, your first conversations. No card required.'}</p><button class="btn secondary small" data-action="${S.demo?'register':'plans'}">${S.demo?'Start your free trial':'View plans'} ${icon('arrow')}</button></div><div class="account"><span class="avatar">${esc(initials(S.demo?'Alex Morgan':S.email))}</span><div><strong>${S.demo?'Alex Morgan':'Workspace owner'}</strong><small>${S.demo?'Demo workspace':'Signed in'}</small></div><button class="btn ghost" data-action="logout" aria-label="Sign out">${icon('logout')}</button></div></div></aside><div class="appmain"><header class="topbar"><div class="crumb"><button class="btn ghost small mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><span>Workspace</span><span>/</span><b>${esc(navItems.find(n=>n[0]===S.page)?.[2]||'Set up your business')}</b></div><div class="actions">${S.demo?'<span class="sample-tag">Fictional sample data</span>':`<span class="pill">${S.business?.plan==='trial'?'7-day trial':'Workspace'}</span>`}<button class="btn secondary small" data-action="preview">${icon('external')} Preview widget</button></div></header><main id="main" class="content">${content}</main></div></div>`;}
function head(title,description,actions=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;}
function aiNotice(){if(S.demo)return '';const status=S.usage?.aiStatus||'untested';return status==='unavailable'?'<div class="callout warn"><span><strong>AI replies need attention.</strong> The last model request was unavailable. Customer messages are still saved and human support works. Check the widget before relying on automated answers.</span></div>':status==='untested'?'<div class="callout"><span><strong>Test your assistant before launch.</strong> Add an approved source, open Preview widget, and ask a question answered by that source. A generated answer should show its company source.</span></div>':'';}
function overview(){const waiting=S.conversations.filter(c=>c.mode==='waiting'&&c.status!=='closed').length,closed=S.conversations.filter(c=>c.status==='closed').length;return shell(`${head('A little more clarity. A lot better support.','Your conversations, company knowledge, and customer experience—all connected.',`<button class="btn" data-action="install">Install your widget ${icon('arrow')}</button>`)}${aiNotice()}<div class="stats">${[['Conversations',S.conversations.length,'chat','Across this workspace'],['Waiting for a person',waiting,'user','Ready for your team'],['Approved sources',S.sources.filter(s=>s.approved).length,'book','Available to your assistant'],['Closed conversations',closed,'shield','Ready to review & export']].map(([l,v,i,n])=>`<div class="stat"><div class="statlabel">${l}${icon(i)}</div><strong>${v}</strong><small>${n}</small></div>`).join('')}</div><div class="columns"><section class="panel"><div class="panelhead"><h3>Your launch checklist</h3><span class="pill">${S.sources.some(s=>s.approved)?'2':'1'} of 3 ready</span></div><div class="panelbody"><div class="setupstep"><span class="stepmark">✓</span><div><strong>Make it your business</strong><p>Name, greeting, website, and brand color.</p></div><button class="link" data-action="settings">Edit</button></div><div class="setupstep"><span class="stepmark">${S.sources.some(s=>s.approved)?'✓':'2'}</span><div><strong>Give your assistant good sources</strong><p>Add and approve your company knowledge.</p></div><button class="link" data-action="knowledge">Open</button></div><div class="setupstep"><span class="stepmark">3</span><div><strong>Connect your customer experience</strong><p>Copy the snippet or open your hosted chat.</p></div><button class="link" data-action="install">Connect</button></div></div></section><section class="panel"><div class="panelhead"><h3>From the first hello to the final record</h3>${icon('shield')}</div><div class="panelbody"><p class="tiny muted">AI and human replies stay in one timeline. Existing messages cannot be edited in the app. Closing a conversation creates a protected archive.</p><div class="integrity"><strong>${icon('shield')} A record both sides can keep</strong>Source citations, timestamps, handoff events, and a verifiable transcript. Corrections are new messages.</div><div class="quicklinks"><button class="quick" data-action="inbox">${icon('chat')}<strong>Open the inbox</strong><small>Pick up a conversation →</small></button><button class="quick" data-action="records">${icon('download')}<strong>Review records</strong><small>Verify and export →</small></button></div></div></section></div><section class="panel dashboardtable"><div class="panelhead"><h3>Recent conversations</h3><button class="link" data-action="inbox">View inbox →</button></div>${conversationTable(S.conversations.slice(0,5))}</section>`);}
function conversationTable(list){if(!list.length)return empty('chat','The next conversation starts here.','Install your widget or preview it to start a real conversation.');return `<div class="tablewrap"><table class="table"><thead><tr><th>Customer</th><th>Category</th><th>Status</th><th>Messages</th><th>Updated</th><th></th></tr></thead><tbody>${list.map(c=>`<tr><td><button data-action="open-chat" data-id="${esc(c.id)}">${esc(c.name)}</button><small>${esc(c.preview.slice(0,55))}</small></td><td>${esc(c.category)}</td><td>${pill(c)}</td><td>${c.seq}</td><td>${esc(new Date(c.updatedAt).toLocaleDateString())}</td><td><button data-action="open-chat" data-id="${esc(c.id)}" aria-label="Open conversation with ${esc(c.name)}">${icon('external')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function empty(i,title,description){return `<div class="empty">${icon(i)}<h3>${title}</h3><p>${description}</p></div>`;}
function inbox(){return shell(`${head('Inbox','One conversation. The right person, at the right moment.',`<button class="btn secondary small" data-action="refresh">${icon('refresh')} Refresh</button>`)}<div class="toolbar"><div class="filters">${[['all','All'],['waiting','Needs a person'],['ai','AI assistant'],['human','With team'],['closed','Closed']].map(([id,label])=>`<button class="filter ${S.filter===id?'active':''}" data-action="filter" data-value="${id}">${label}</button>`).join('')}</div><span class="tiny muted">${S.demo?'Sample workspace':'Updates every 8 seconds'}</span></div><div class="inbox ${S.selected?'selected':''}"><section class="conversation-list" aria-label="Conversations"><div class="listsearch"><input id="chat-search" placeholder="Search conversations…" aria-label="Search conversations" value="${esc(S.search)}"></div><div id="conversation-items">${conversationItems()}</div></section><section class="thread" aria-label="Conversation">${thread()}</section><aside class="threadinfo">${threadInfo()}</aside></div>`);}
function conversationItems(){const list=S.conversations.filter(c=>(S.filter==='all'||(S.filter==='closed'?c.status==='closed':c.mode===S.filter&&c.status!=='closed'))&&(c.name+' '+c.preview).toLowerCase().includes(S.search.toLowerCase()));return list.length?list.map(c=>`<button class="convitem ${S.selected?.id===c.id?'active':''}" data-action="open-chat" data-id="${esc(c.id)}"><div class="convtop"><span class="avatar">${esc(initials(c.name))}</span><strong>${esc(c.name)}</strong><time>${esc(new Date(c.updatedAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}))}</time></div><p>${esc(c.preview)}</p>${pill(c)}</button>`).join(''):empty('chat','All clear.','No conversations match this view.');}
function messageHtml(m,index){if(m.role==='system')return `<div class="msgsystem">${icon('shield')} ${esc(m.content)}</div>`;return `<article class="msg ${esc(m.role)}"><div class="msgmeta"><strong>${m.role==='customer'?esc(S.selected?.name||'Customer'):m.role==='assistant'?'AI assistant':esc(S.business.agentName)+' · Human agent'}</strong><time>${esc(new Date(m.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}))}</time></div><div class="msgbody">${esc(m.content)}</div>${m.sources?.length?`<div class="msgsources">${m.sources.map((s,j)=>`<button class="sourcechip" data-action="citation" data-message="${index}" data-source="${j}">↳ ${esc(s.title)}</button>`).join('')}</div>`:''}</article>`;}
function thread(){const c=S.selected;if(!c)return empty('chat','A conversation is waiting to happen.','Choose a conversation on the left, or preview your widget.');return `<div class="threadhead"><button class="btn ghost small mobile-menu" data-action="chat-list" aria-label="Back to conversations">←</button><span class="avatar">${esc(initials(c.name))}</span><div><strong>${esc(c.name)}</strong><small>${esc(c.category)} · ${pill(c)}</small></div><div class="actions">${c.status!=='closed'&&c.mode!=='human'?'<button class="btn small" data-action="takeover">Join conversation</button>':''}${c.status!=='closed'?'<button class="btn secondary small" data-action="close-chat">Close</button>':`<button class="btn secondary small" data-action="export">Export</button>${!c.archive?'<button class="btn small" data-action="confirm-close">Retry archive</button>':''}`}</div></div><div class="threadbody" id="thread-messages" role="log" aria-live="polite">${(c.messages||[]).map(messageHtml).join('')}</div><div class="composer">${c.status==='closed'?'<div class="integrity"><strong>This conversation is read-only.</strong>Verify the transcript or download a copy for your records.</div>':c.mode==='human'?`<form id="reply-form"><div class="composerbox"><label for="reply" class="tiny muted">Reply as ${esc(S.business.agentName)}</label><textarea id="reply" required maxlength="4000" placeholder="Write a thoughtful reply…">${esc(S.replyDraft)}</textarea><div class="composerfoot"><span>Replies become part of the preserved record.</span><button type="submit" class="btn small">Send reply ${icon('arrow')}</button></div></div></form>`:`<div class="callout ${c.mode==='waiting'?'warn':''}"><span>${c.mode==='waiting'?'This customer asked for a person. Join to take over with the full context.':'AI is handling this conversation. Join whenever a human touch would help.'}</span></div>`}</div>`;}
function threadInfo(){const c=S.selected;if(!c)return '';return `<span class="avatar">${esc(initials(c.name))}</span><h3>${esc(c.name)}</h3><span class="tiny muted">Customer-provided name</span><div class="infosection"><h4>Conversation details</h4><div class="inforow"><span>Category</span><b>${esc(c.category)}</b></div><div class="inforow"><span>Messages</span><b>${c.seq}</b></div><div class="inforow"><span>Started</span><b>${esc(new Date(c.createdAt).toLocaleDateString())}</b></div><div class="inforow"><span>Handled by</span><b>${c.mode==='human'?'Your team':c.mode==='waiting'?'Waiting':'AI assistant'}</b></div></div>${c.status==='closed'?`<div class="infosection"><h4>Customer feedback</h4>${c.feedback?`<p>Resolved: <strong>${esc({yes:'Yes',partly:'Partly',no:'No'}[c.feedback.resolution])}</strong><br>Helpfulness: <strong>${esc(c.feedback.rating)} / 5</strong></p>${c.feedback.comment?`<p>${esc(c.feedback.comment)}</p>`:''}<p class="tiny muted">Customer-reported feedback, stored separately from the sealed record.</p>`:'<p class="muted">No optional feedback received.</p>'}</div>`:''}<div class="infosection"><h4>Record integrity</h4><div class="integrity"><strong>${icon('shield')} Append-only timeline</strong>Messages are added, never rewritten.${c.archive?'<br>Closed record archived.':''}</div><div class="actions"><button class="link" data-action="verify">Verify record</button><button class="link" data-action="export">Export JSON</button></div></div><div class="infosection"><h4>Knowledge available</h4><ul class="sourcelist">${S.sources.filter(x=>x.approved).map(x=>`<li>${icon('file')} ${esc(x.title)}</li>`).join('')||'<li>No approved sources yet.</li>'}</ul></div>`;}
function knowledge(){return shell(`${head('A good answer starts with good knowledge.','Give your assistant the company information it can confidently use.',`<button class="btn" data-action="add-source">${icon('plus')} Add knowledge</button>`)}<div class="callout">${icon('shield')}<span>Only approved sources are used in customer answers. Review imported content before approving it. LinkedIn and social content can be added as authorized text exports.</span></div>${S.sources.length?`<div class="cardgrid">${S.sources.map(s=>`<article class="sourcecard">${icon(s.kind==='url'?'globe':'file')}<h3>${esc(s.title)}</h3><p>${esc(s.content)}</p><div class="sourcefoot"><span class="pill ${s.approved?'':'waiting'}">${s.approved?'Approved':'Review needed'}</span><button class="link" data-action="view-source" data-id="${esc(s.id)}">Review →</button></div></article>`).join('')}</div>`:`<section class="panel">${empty('book','Your knowledge library starts here.','Add a return policy, a product FAQ, or a public page from your company website.')}</section>`}<p class="retention-note">Pilot sources: plain text, Markdown/text exports, and text-based PDFs up to 350 KB / 20 pages. Website imports read one public page at a time. Scanned files and login-protected social profiles need an authorized text export.</p>`);}
function addSourceModal(){modal(`${mhead('Add company knowledge')}<p>Choose content you’re authorized to share with customers.</p><div class="integration-tabs">${[['text','Paste text'],['pdf','Upload PDF'],['url','Website page']].map(([id,label])=>`<button data-action="source-kind" data-value="${id}" class="${S.sourceKind===id?'active':''}">${label}</button>`).join('')}</div><form id="source-form"><div class="field"><label for="source-title">Source title</label><input id="source-title" required maxlength="150" placeholder="e.g. Returns & exchanges"></div>${S.sourceKind==='text'?'<div class="field"><label for="source-content">Company information</label><textarea id="source-content" class="tall" required minlength="30" maxlength="40000" placeholder="Paste your policy, FAQ, or authorized company export…"></textarea><label for="text-file">Or choose a .txt / .md file</label><input id="text-file" type="file" accept=".txt,.md,text/plain"></div>':S.sourceKind==='pdf'?'<div class="field"><label for="source-file">Text-based PDF</label><input id="source-file" type="file" accept="application/pdf,.pdf" required><small>Up to 350 KB, 20 pages. Scanned images and encrypted documents aren’t supported.</small></div>':'<div class="field"><label for="source-url">Public page URL</label><input id="source-url" type="url" required placeholder="https://yourcompany.com/returns"><small>The website origin must be in your business settings. Imports do not follow links or sign in to accounts.</small></div>'}<label class="check"><input type="checkbox" id="source-approved"><span>I have reviewed this content and approve its use in customer answers. Otherwise, save it for review first.</span></label><div id="form-error" class="error hidden" role="alert" tabindex="-1"></div><button class="btn" type="submit">Add source ${icon('arrow')}</button></form>`);}
function snippets(){const id=S.business?.siteId||'YOUR_SITE_ID',base=location.origin,url=`${base}/widget/${id}?standalone=1`;return {website:`<script src="${base}/embed.js"\n  data-site="${id}" defer><\/script>`,react:`import { useEffect } from 'react';\n\nexport function SupportWidget() {\n  useEffect(() => {\n    const script = document.createElement('script');\n    script.src = '${base}/embed.js';\n    script.dataset.site = '${id}';\n    script.async = true;\n    document.body.appendChild(script);\n    return () => {\n      window.OrderProof?.destroy();\n      script.remove();\n    };\n  }, []);\n  return null;\n}`,ios:`import WebKit\n\nlet supportView = WKWebView(frame: .zero)\nlet supportURL = URL(string: "${url}")!\nsupportView.load(URLRequest(url: supportURL))\n// Present in your support screen and constrain it\n// to your view's safe-area layout guides.`,android:`// AndroidManifest.xml: INTERNET permission required.\nval support = WebView(context)\nsupport.webViewClient = WebViewClient()\nsupport.settings.javaScriptEnabled = true\nsupport.settings.domStorageEnabled = true\nsupport.loadUrl("${url}")\n// Do not add a JavaScript interface or allow mixed content.`,standalone:url,api:`POST ${base}/public/support/sites/${id}/conversations\nContent-Type: application/json\n\n{"name":"Customer","category":"general","consent":true}\n\n// Save the returned token securely. Never place it in a URL.\nPOST ${base}/public/support/conversations/CONVERSATION_ID/messages\nX-Conversation-Token: RETURNED_TOKEN\nContent-Type: application/json\n\n{"content":"How do returns work?","requestId":"UNIQUE_REQUEST_ID"}\n\n// GET the conversation with the same header for updates.\n// POST /handoff to request a human. GET /export for the record.`};}
function install(publicView=false){const selected=S.platform,code=snippets()[selected],names={website:'Website',react:'React / web app',ios:'iOS',android:'Android',standalone:'Hosted chat',api:'Custom API'};const body=`${head('Meet customers wherever they are.','One business, one inbox. Connect the experience that fits your product.',S.business?'<button class="btn secondary small" data-action="preview">Preview your chat ↗</button>':'')}<div class="integration-tabs">${Object.entries(names).map(([id,name])=>`<button class="${id===selected?'active':''}" data-action="platform" data-value="${id}">${name}</button>`).join('')}</div><div class="columns"><section class="panel"><div class="panelhead"><h3>${names[selected]} installation</h3><span class="pill">${selected==='api'?'REST API':selected==='standalone'?'No code':'Quick setup'}</span></div><div class="panelbody"><p class="tiny muted">${({website:'Add this before your website’s closing body tag. The widget appears in the bottom-right corner.',react:'Mount this client-side component once in your application layout.',ios:'Present your hosted support experience using Apple WKWebView. No AWS credentials belong in the app.',android:'Present your hosted support experience in Android WebView with HTTPS and JavaScript enabled.',standalone:'Open this link as a dedicated support page, or add it to your app’s Help menu.',api:'Build a custom customer interface using the same session, message, handoff, and transcript API.'})[selected]}</p><pre class="codebox" id="install-code">${esc(code)}</pre><div class="actions"><button class="btn secondary small" data-action="copy-code">${icon('copy')} Copy ${selected==='standalone'?'link':'code'}</button>${selected==='standalone'&&S.business?`<a class="btn small" href="${S.demo?'/widget-demo?standalone=1':esc(code)}" target="_blank" rel="noopener">Open hosted chat ↗</a>`:''}</div><div class="installsteps"><div class="installstep">Add your website’s exact HTTPS origin in Settings. Embedded browser frames are allowed only on configured origins.</div><div class="installstep">Add and approve your knowledge sources. Your assistant won’t invent missing company information.</div><div class="installstep">Test a customer question, a human handoff, and a transcript export before launch.</div></div>${selected==='website'||selected==='react'?'<div class="callout">If your website uses Content Security Policy, allow this service’s origin in script-src, style-src, and frame-src. Customer API calls stay inside the isolated widget.</div>':''}${selected==='api'?'<div class="callout">Native apps and your server can call this API directly. Browser custom clients need a same-origin backend proxy; cross-origin public API access is not enabled. Bearer session tokens are scoped to one conversation.</div>':''}</div></section><aside><div class="preview-window"><div class="fake-browser"><i></i><i></i><i></i></div><div class="preview-content"><div class="eyebrow">${esc(S.business?.name||'Your business')}</div><h3>A thoughtful experience.<br>Right where you need it.</h3><p>Your website or app. Your brand. A helping hand, one tap away.</p></div><button class="preview-launch" data-action="preview" aria-label="Preview customer chat">${icon('chat')}</button></div><p class="retention-note">Mobile examples are integration starting points, not separately built App Store or Play Store apps. A native chat UI can use the same REST API.</p><button class="link" data-action="api-docs">Read the API guide →</button></aside></div>`;return publicView?`${publicNav()}<main id="main" class="section">${body}</main>${footer()}`:shell(body);}
function records(){return shell(`${head('What was said. Kept together.','Review, verify, and export the complete customer conversation.')}<div class="callout good">${icon('shield')}<span>Messages cannot be edited or deleted through the application. Closed transcripts are archived with 30-day S3 governance protection and a verifiable digest.</span></div><section class="panel"><div class="panelhead"><h3>Conversation records</h3><span class="tiny muted">90-day pilot history</span></div>${conversationTable(S.conversations)}</section><p class="retention-note">Hash verification detects inconsistencies in the recorded chain. It does not independently verify a customer’s identity. Authorized AWS administrators with governance-bypass privileges can override archive retention; this is not a claim of absolute immutability or regulatory certification.</p>`);}
function planCards(){return `<div class="plans">${Object.entries(plans).map(([id,p])=>`<article class="plan ${id==='growth'?'featured':''}">${id==='growth'?'<span class="pill">More room to grow</span>':''}<h3>${p.name}</h3><p>${p.description}</p><div class="planprice">$${p.price}<span> USD / month</span></div><ul>${p.features.map(f=>`<li>${f}</li>`).join('')}</ul><button class="btn ${id==='growth'?'':'secondary'}" data-action="choose-plan" data-value="${id}">${S.business?.requestedPlan===id?'Selected for later':'Choose '+p.name} ${icon('arrow')}</button></article>`).join('')}</div>`;}
function billing(publicView=false){const u=S.usage||{},body=`${head('Start small. Keep the whole conversation.','Try OrderProof free for 7 days. Choose the room your business needs.')}<div class="callout warn"><span><strong>No card required. No automatic charge.</strong> Stripe checkout is not connected yet. Paid plans below are proposed launch offers; selecting one saves a preference and does not activate paid usage.</span></div>${!publicView?`<section class="panel"><div class="panelbody"><div class="pagehead"><div><h3>Your ${S.business?.reviewAccessUntil>Date.now()/1000?'reviewer access':S.business?.plan==='trial'?'7-day free trial':'current plan'}</h3><p>${trialDays()} days remaining · ${u.aiUsed||0} of ${u.aiLimit||100} AI answer attempts used this month</p></div><span class="pill">${S.demo?'Sample usage':'No payment method'}</span></div><div class="usagebar"><span id="usage-fill"></span></div><small class="tiny">Trial includes 100 AI answer attempts, 20 sources, and 3 website origins. A shared pilot cost ceiling also applies.</small></div></section>`:''}${planCards()}<p class="retention-note">All launch plans include one owner-operated human inbox, cited AI answers, app integrations, transcript exports, and 90-day history. Team seats, voice calls, and payment processing are not included. After a trial expires, records stay readable and exportable; new support activity pauses until billing is activated. Proposed plans may change before paid launch.</p>`;return publicView?`${publicNav()}<main id="main" class="section">${body}</main>${footer()}`:shell(body);}
function settings(onboarding=false){const b=S.business||{};return shell(`<div class="${onboarding?'onboarding':''}">${head(onboarding?'Make your customers feel at home.':'Your business. Your voice.',onboarding?'Set up your workspace. Your 7-day trial starts when you save.':'Keep your identity, website connections, and welcome message up to date.')}<section class="panel"><div class="panelhead"><h3>Business details</h3>${onboarding?'<span class="pill">First step</span>':''}</div><form id="settings-form" class="panelbody"><div class="fields2"><div class="field"><label for="biz-name">Business name</label><input id="biz-name" required maxlength="100" value="${esc(b.name||'')}" placeholder="e.g. Evergreen Studio"></div><div class="field"><label for="biz-agent">Human agent display name</label><input id="biz-agent" required maxlength="80" value="${esc(b.agentName||'Support team')}"></div></div><div class="field"><label for="biz-website">Company website origin</label><input id="biz-website" type="url" required value="${esc(b.website||'')}" placeholder="https://www.yourcompany.com"><small>Use HTTPS and the exact hostname, without a page path.</small></div><div class="field"><label for="biz-domains">Additional allowed website origins</label><textarea id="biz-domains" placeholder="https://app.yourcompany.com">${esc((b.domains||[]).filter(d=>d!==b.website).join('\n'))}</textarea><small>One origin per line. The trial supports three origins total. Add both www and non-www if you use both.</small></div><div class="field"><label for="biz-description">About your business</label><textarea id="biz-description" maxlength="500" placeholder="A short description for your workspace…">${esc(b.description||'')}</textarea></div><div class="field"><label for="biz-greeting">Customer welcome message</label><textarea id="biz-greeting" required maxlength="300">${esc(b.greeting||'Hi! Welcome to our support chat. How can we help you today?')}</textarea><small>The widget also identifies itself as AI and offers a human handoff.</small></div><div class="field"><label for="biz-color">Widget brand color</label><input id="biz-color" type="color" value="${esc(b.color||'#245e4c')}"><small>Text contrast adjusts automatically to your brand color.</small></div><label class="check"><input type="checkbox" id="biz-email-notices" ${b.emailNotifications?'checked':''} ${!S.demo&&!S.config?.emailConfigured?'disabled':''}><span>Email me human-handoff and closed-record notifications. ${S.config?.emailConfigured?'Sent only to your verified account email, up to five notices per day. Always check your in-app inbox.':'Branded sending is awaiting a verified sender setup; the in-app inbox works now.'}</span></label><p class="tiny"><a href="/email-preview" target="_blank" rel="noopener">Preview our email designs ↗</a></p><div id="form-error" class="error hidden" role="alert" tabindex="-1"></div><button class="btn" type="submit">${onboarding?'Create workspace & start trial':'Save settings'} ${icon('arrow')}</button></form></section><p class="retention-note">Company information becomes available to the assistant only when you add it as an approved knowledge source. Settings descriptions are not silently treated as policies.</p></div>`);}
function emailGuidance(){return `<div class="email-help"><p><strong>Finding your code</strong></p><p>${S.deliveryDestination?'AWS accepted a code request for '+esc(S.deliveryDestination)+'.':'If you do not have a current code, request a new one.'} Delivery can take a few minutes.</p><p>Check Spam and All Mail. Search for “verification” or ${S.config?.emailConfigured?'“OrderProof”':'“no-reply@verificationemail.com”'}. Use the newest code and never share it.</p>${S.authMode==='reset'?'<button type="button" class="link" data-action="forgot">Request another reset code</button>':''}</div>`;}
function rememberPending(mode){try{sessionStorage.setItem('orderproof-pending-auth',JSON.stringify({email:S.email,mode}));}catch{}}
function clearPending(){try{sessionStorage.removeItem('orderproof-pending-auth');}catch{}}
function delivered(result){S.deliveryDestination=result.CodeDeliveryDetails?.Destination||'';S.resendUntil=Date.now()+60000;}
function auth(){const mode=S.authMode,titles={login:'Welcome back.',register:'Great support starts here.',confirm:'Check your inbox.',forgot:'Let’s get you back in.',reset:'Choose a new password.'};return `${publicNav()}<main id="main" class="auth"><div class="eyebrow">Your business workspace</div><h1>${titles[mode]}</h1><p class="tiny muted">${mode==='register'?'Start your 7-day free trial. No credit card required.':mode==='confirm'?'Enter the latest verification code for your email address.':'Your team’s conversations, in one place.'}</p><section class="panel"><form id="auth-form" class="panelbody"><div class="field"><label for="email">Email address</label><input id="email" type="email" autocomplete="email" required value="${esc(S.email)}"></div>${['confirm','reset'].includes(mode)?'<div class="field"><label for="code">Verification code</label><input id="code" autocomplete="one-time-code" inputmode="numeric" maxlength="12" spellcheck="false" required></div>':''}${['login','register','reset'].includes(mode)?`<div class="field"><label for="password">Password</label><input id="password" type="password" required minlength="${mode==='login'?1:12}" autocomplete="${mode==='login'?'current-password':'new-password'}">${mode!=='login'?'<small>12+ characters, with upper and lowercase letters, a number, and a symbol.</small>':''}</div>`:''}<div id="form-error" class="error hidden" role="alert" tabindex="-1"></div><button class="btn" type="submit">${({login:'Sign in',register:'Create your account',confirm:'Verify email',forgot:'Send reset code',reset:'Reset password'})[mode]}</button><div class="authlinks"><button class="link" type="button" data-action="${mode==='login'?'register':'login'}">${mode==='login'?'Create an account':'Back to sign in'}</button>${mode==='login'?'<button class="link" type="button" data-action="forgot">Forgot password?</button>':mode==='confirm'?'<button class="link" type="button" data-action="resend">Resend code</button>':''}</div>${['confirm','reset'].includes(mode)?emailGuidance():''}</form></section><p class="retention-note">By creating an account, you acknowledge the <a href="/privacy" data-action="privacy">privacy and retention notice</a>. Your free trial begins when you set up your business.</p></main>${footer()}`;}
function privacy(){return `${publicNav()}<main id="main" class="legal"><div class="eyebrow">Privacy & retention · September 20, 2026</div><h1>Helpful support needs clear boundaries.</h1><p>OrderProof is an early-stage business support service. Businesses should upload only information they are authorized to use and approve sources intended for customer answers. Avoid card numbers, passwords, identity documents, and sensitive medical information in chats.</p><h2>What is recorded</h2><p>Customer, AI, human-agent, and system messages are recorded with timestamps and source references. Customers consent before starting a chat. The name entered by a customer is self-reported, not independently verified. Businesses have access to their own conversations; customers access a single conversation using a private token.</p><h2>Company knowledge and AI</h2><p>Approved company passages and recent conversation context are sent to Amazon Bedrock in US West (Oregon). Application records are stored on AWS in US East (N. Virginia). The assistant can make mistakes; businesses remain responsible for their policies and human review. It cannot access a customer’s order system, issue refunds, or take payments.</p><h2>Append-only records and retention</h2><p>Messages cannot be edited or deleted through the application. Corrections must be new messages. Chat records are scheduled to expire after 90 days. When a conversation closes, its transcript is archived in a private, versioned S3 bucket with 30-day governance protection. Archived transcripts are scheduled for expiration 90 days after closure; older versions expire after one further day. Deletion is asynchronous and archived retention can extend beyond the chat’s 90-day access period. Authorized AWS administrators with special governance-bypass permissions can override protection. Hash checks detect inconsistency; they are not an independent proof of identity or regulatory certification.</p><h2>Your controls</h2><p>Businesses can remove knowledge sources or withdraw their approval for future answers. Previously recorded messages and their citations remain in the conversation record until retention expires. Both parties can export the transcript. Contact the business operating the widget for privacy requests; AWS administrators can handle exceptional retention requests. Account deletion is not yet self-service.</p><h2>Sessions and analytics</h2><p>The customer widget keeps its conversation token in session storage for the current tab. Seller login tokens remain in memory and expire; reloads require sign-in. The interactive sample uses fictional content and no live model calls. No advertising or third-party analytics are installed. Operational logs retain metadata for seven days and do not intentionally include message bodies or tokens.</p><h2>Trial and proposed subscriptions</h2><p>The free trial lasts seven days from workspace creation. No card is required, and no automatic payment is taken. Stripe is not connected yet. Plan selections only save a preference. When the trial expires, new support activity pauses while existing records remain available for reading and export.</p><button class="btn secondary" data-action="${S.business?'overview':'home'}">Back</button></main>${footer()}`;}
function render(){const pages={landing,overview,inbox,knowledge,install,records,plans:billing,settings,setup:()=>settings(true),auth,privacy,'public-install':()=>install(true),'public-plans':()=>billing(true)};root.innerHTML=(pages[S.page]||landing)();if(S.page==='plans'&&$('#usage-fill'))$('#usage-fill').style.width=Math.min(100,(S.usage?.aiUsed||0)/(S.usage?.aiLimit||100)*100)+'%';scrollThread();}
function scrollThread(){const el=$('#thread-messages');if(el)el.scrollTop=el.scrollHeight;}
async function config(){if(!S.config){const r=await fetch('/config');S.config=await r.json();}return S.config;}
async function cognito(action,data){const c=await config();if(!c.clientId)throw new Error('Sign-in is not configured in local preview. Explore the sample workspace.');const r=await fetch(`https://cognito-idp.${c.region}.amazonaws.com/`,{method:'POST',headers:{'Content-Type':'application/x-amz-json-1.1','X-Amz-Target':`AWSCognitoIdentityProviderService.${action}`},body:JSON.stringify({ClientId:c.clientId,...data})});const out=await r.json();if(!r.ok){const e=new Error(out.message||'Authentication failed.');e.code=out.__type;throw e;}return out;}
async function api(path,method='GET',data){const r=await fetch('/api/support/'+path,{method,headers:{'Content-Type':'application/json',Authorization:`Bearer ${S.token}`},...(data?{body:JSON.stringify(data)}:{})});let out;try{out=await r.json();}catch{throw new Error('The server could not complete this request. Please try again.');}if(!r.ok){if(r.status===401){S.token=null;S.authMode='login';go('auth');}throw new Error(out.error||out.message||'Request failed.');}return out;}
async function refreshAll(){S.business=await api('business');if(!S.business){go('setup');return;}[S.sources,S.conversations,S.usage]=await Promise.all([api('sources'),api('conversations'),api('usage')]);}
async function enter(){S.demo=false;await refreshAll();if(S.business)go('overview');}
async function openChat(id){S.replyDraft='';S.selected=S.demo?S.conversations.find(c=>c.id===id):await api('conversations/'+id);go('inbox');}
function updateChat(c){S.selected=c;const i=S.conversations.findIndex(x=>x.id===c.id);if(i<0)S.conversations.unshift(c);else S.conversations[i]=c;}
function demoAppend(role,content,updates={}){const c=S.selected;c.messages.push({role,content,sequence:++c.seq,at:new Date().toISOString(),sources:[]});Object.assign(c,updates,{updatedAt:new Date().toISOString(),preview:content});updateChat(c);}
async function busy(fn,button){if(S.busy)return;S.busy=true;const label=button?.innerHTML;if(button){button.disabled=true;button.textContent='Working…';}try{await fn();}catch(e){error(e);}finally{S.busy=false;if(button?.isConnected){button.disabled=false;button.innerHTML=label;}}}
function download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const el=document.createElement('a');el.href=url;el.download=name;el.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function preview(){if(!S.business){demoData();}modal(`<div class="previewtop"><span>${S.demo?'Fictional customer walkthrough':'Your live customer widget'}</span><button class="close" data-action="close-modal" aria-label="Close preview">×</button></div><iframe title="Customer support preview" src="${S.demo?'/widget-demo?standalone=1':'/widget/'+S.business.siteId+'?standalone=1'}"></iframe>`,'widget-preview');}
async function onAction(el){const action=el.dataset.action;if(navItems.some(x=>x[0]===action)){if(!S.business&&action!=='settings'){go('setup');return;}if(!S.demo){if(action==='knowledge')S.sources=await api('sources');if(action==='inbox'||action==='records')S.conversations=await api('conversations');if(action==='plans'||action==='overview')S.usage=await api('usage');}go(action);return;}switch(action){case'home':history.replaceState({},'','/');go('landing');break;case'privacy':go('privacy');break;case'demo':demoData();break;case'public-integrations':go('public-install');break;case'public-plans':go('public-plans');break;case'login':case'register':case'forgot':S.authMode=action;go('auth');break;case'logout':S.token=null;S.demo=false;S.business=null;S.selected=null;S.sources=[];S.conversations=[];go('landing');break;case'menu':$('.sidebar').classList.toggle('open');break;case'preview':await preview();break;case'filter':S.filter=el.dataset.value;render();break;case'open-chat':await openChat(el.dataset.id);break;case'chat-list':S.selected=null;render();break;case'refresh':if(!S.demo){S.conversations=await api('conversations');if(S.selected)S.selected=await api('conversations/'+S.selected.id);}render();break;case'takeover':if(S.demo)demoAppend('system',S.business.agentName+' joined the conversation.',{mode:'human',status:'active'});else updateChat(await api('conversations/'+S.selected.id+'/takeover','POST',{requestId:crypto.randomUUID()}));render();break;case'close-chat':modal(`${mhead('Close and preserve this conversation?')}<p>The chat will become read-only. Its full transcript will be archived with 30-day governance protection. Neither side can add or edit messages afterward.</p><div class="actions"><button class="btn" data-action="confirm-close">Close conversation</button><button class="btn secondary" data-action="close-modal">Keep open</button></div>`);break;case'confirm-close':if(S.demo){demoAppend('system','Sample conversation closed. No real archive has been created.',{status:'closed',archive:{demo:true}});}else updateChat(await api('conversations/'+S.selected.id+'/close','POST',{requestId:crypto.randomUUID()}));closeModal();render();toast('Conversation closed.');break;case'verify':if(S.demo){modal(`${mhead('A look at record verification')}<p>This fictional walkthrough has no server-side archive. Real conversations are checked against their message hash chain and, after closing, their protected archive version.</p><button class="btn" data-action="close-modal">Got it</button>`);}else{const r=await api('conversations/'+S.selected.id+'/verify');modal(`${mhead(r.valid?'The record checks out.':'Record verification failed')}<div class="callout ${r.valid?'good':'warn'}">${r.messageCount} messages checked. ${r.archiveValid?'The protected archive matches.':r.archive?'Archive check needs attention.':'The conversation has not been archived yet.'}</div><p class="mono">${esc(r.lastDigest||r.reason||'')}</p><p>Verification checks the stored chain. It does not independently verify the customer’s identity.</p><button class="btn" data-action="close-modal">Done</button>`);}break;case'export':download(S.demo?{demo:true,...S.selected}:await api('conversations/'+S.selected.id+'/export'),'orderproof-'+S.selected.id+'.json');break;case'citation':{const source=S.selected.messages[Number(el.dataset.message)].sources[Number(el.dataset.source)];modal(`${mhead(esc(source.title))}<p>${esc(source.excerpt)}</p><p class="tiny">This is the source passage used for this response.</p><button class="btn secondary" data-action="close-modal">Close</button>`);break;}case'add-source':S.sourceKind='text';addSourceModal();break;case'source-kind':S.sourceKind=el.dataset.value;closeModal();addSourceModal();break;case'view-source':{const s=S.sources.find(x=>x.id===el.dataset.id);modal(`${mhead(esc(s.title))}<p class="tiny muted">${s.kind.toUpperCase()} · ${s.approved?'Approved for customer answers':'Awaiting your review'}</p><pre class="codebox">${esc(s.content)}</pre><div class="actions"><button class="btn" data-action="approve-source" data-id="${esc(s.id)}">${s.approved?'Withdraw approval':'Approve for answers'}</button><button class="btn danger" data-action="delete-source" data-id="${esc(s.id)}">Remove source</button></div>`,'wide');break;}case'approve-source':{const s=S.sources.find(x=>x.id===el.dataset.id);if(!S.demo)await api('sources/'+s.id,'PUT',{approved:!s.approved});s.approved=!s.approved;closeModal();render();toast('Source approval updated.');break;}case'delete-source':if(!S.demo)await api('sources/'+el.dataset.id,'DELETE');S.sources=S.sources.filter(x=>x.id!==el.dataset.id);closeModal();render();toast('Source removed from future answers. Existing records remain unchanged.');break;case'platform':S.platform=el.dataset.value;render();break;case'copy-code':await navigator.clipboard.writeText(snippets()[S.platform]);toast('Copied to clipboard.');break;case'choose-plan':if(!S.business){S.authMode='register';go('auth');return;}if(S.demo)S.business.requestedPlan=el.dataset.value;else{const r=await api('select-plan','POST',{plan:el.dataset.value});S.business.requestedPlan=r.requestedPlan;}render();toast('Plan preference saved. Stripe is not connected; no charge or upgrade has occurred.');break;case'api-docs':S.platform='api';go(S.business?'install':'public-install');break;case'resend':if(Date.now()<S.resendUntil){toast('Please wait a moment before requesting another code.');break;}S.email=$('#email').value.trim();delivered(await cognito('ResendConfirmationCode',{Username:S.email}));rememberPending('confirm');render();toast('AWS accepted the code request. Check your inbox and Spam folder; delivery is not yet confirmed.');break;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();if(el.dataset.action==='close-modal'){closeModal();return;}busy(()=>onAction(el),el.tagName==='BUTTON'?el:null);});
document.addEventListener('input',e=>{if(e.target.id==='chat-search'){S.search=e.target.value;$('#conversation-items').innerHTML=conversationItems();}if(e.target.id==='reply')S.replyDraft=e.target.value;});
document.addEventListener('change',e=>{if(e.target.id==='text-file')busy(async()=>{const file=e.target.files[0];if(file.size>160000)throw new Error('Choose a text file under 160 KB.');const txt=await file.text();if(txt.length>40000)throw new Error('Limit source text to 40,000 characters.');$('#source-content').value=txt;});});
async function authSubmit(){S.email=$('#email').value.trim();const password=$('#password')?.value,code=$('#code')?.value.trim(),mode=S.authMode;if(mode==='register'){const r=await cognito('SignUp',{Username:S.email,Password:password,UserAttributes:[{Name:'email',Value:S.email}]});delivered(r);S.authMode=r.UserConfirmed?'login':'confirm';if(!r.UserConfirmed)rememberPending('confirm');render();}else if(mode==='confirm'){await cognito('ConfirmSignUp',{Username:S.email,ConfirmationCode:code});clearPending();S.authMode='login';render();toast('Email verified. Sign in to create your workspace.');}else if(mode==='forgot'){delivered(await cognito('ForgotPassword',{Username:S.email}));rememberPending('reset');S.authMode='reset';render();}else if(mode==='reset'){await cognito('ConfirmForgotPassword',{Username:S.email,ConfirmationCode:code,Password:password});clearPending();S.authMode='login';render();toast('Password updated.');}else{try{const r=await cognito('InitiateAuth',{AuthFlow:'USER_PASSWORD_AUTH',AuthParameters:{USERNAME:S.email,PASSWORD:password}});if(!r.AuthenticationResult)throw new Error('This account needs an additional sign-in step.');S.token=r.AuthenticationResult.AccessToken;clearPending();await enter();}catch(e){if((e.code||'').includes('UserNotConfirmed')){S.authMode='confirm';rememberPending('confirm');render();}else throw e;}}}
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;busy(async()=>{if(form.id==='auth-form')await authSubmit();if(form.id==='settings-form'){const data={name:$('#biz-name').value.trim(),agentName:$('#biz-agent').value.trim(),website:$('#biz-website').value.trim().replace(/\/$/,''),domains:[$('#biz-website').value.trim().replace(/\/$/,''),...$('#biz-domains').value.split('\n').map(s=>s.trim()).filter(Boolean)],description:$('#biz-description').value.trim(),greeting:$('#biz-greeting').value.trim(),color:$('#biz-color').value,emailNotifications:$('#biz-email-notices').checked,...(S.business?{version:S.business.version}:{})};if(S.demo)S.business={...S.business,...data,version:S.business.version+1};else S.business=await api('business','PUT',data);go('overview');toast('Your business settings are saved.');}if(form.id==='source-form'){const data={title:$('#source-title').value.trim(),kind:S.sourceKind,approved:$('#source-approved').checked};if(S.sourceKind==='text')data.content=$('#source-content').value;else if(S.sourceKind==='url')data.url=$('#source-url').value;else{const f=$('#source-file').files[0];if(f.size>350000)throw new Error('Use a PDF smaller than 350 KB.');const bytes=new Uint8Array(await f.arrayBuffer());let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);data.file=btoa(binary);}if(S.demo){if(S.sourceKind!=='text')throw new Error('The sample workspace supports pasted text only. Create a real workspace to import PDF or website sources.');S.sources.push({...data,id:crypto.randomUUID(),createdAt:new Date().toISOString()});}else S.sources.push(await api('sources','POST',data));closeModal();go('knowledge');toast('Knowledge source added.');}if(form.id==='reply-form'){const content=$('#reply').value.trim();if(!content)return;if(S.demo)demoAppend('agent',content);else updateChat(await api('conversations/'+S.selected.id+'/reply','POST',{content,requestId:crypto.randomUUID()}));S.replyDraft='';render();}},form.querySelector('[type=submit]'));});
setInterval(async()=>{if(S.demo||!S.token||S.busy||document.hidden||S.page!=='inbox')return;try{const list=await api('conversations');S.conversations=list;if($('#conversation-items'))$('#conversation-items').innerHTML=conversationItems();if(S.selected){const latest=await api('conversations/'+S.selected.id);if(latest.seq!==S.selected.seq||JSON.stringify(latest.archive)!==JSON.stringify(S.selected.archive)){S.selected=latest;const field=$('#reply');if(field)S.replyDraft=field.value;$('.thread').innerHTML=thread();$('.threadinfo').innerHTML=threadInfo();scrollThread();}}}catch(e){toast(e.message);}},8000);
setInterval(()=>{const button=document.querySelector('[data-action="resend"]');if(button&&!S.busy){const seconds=Math.max(0,Math.ceil((S.resendUntil-Date.now())/1000));button.disabled=seconds>0;button.textContent=seconds?'Resend in '+seconds+'s':'Resend code';}},1000);
const path=location.pathname;if(path==='/app'){S.page='auth';}else if(path==='/privacy')S.page='privacy';else if(path==='/integrations'||path==='/docs')S.page='public-install';else if(path==='/pricing')S.page='public-plans';try{const pending=JSON.parse(sessionStorage.getItem('orderproof-pending-auth'));if(location.hash!=='#how'&&pending?.email&&['confirm','reset'].includes(pending.mode)&&['/','/app'].includes(path)){S.email=pending.email;S.authMode=pending.mode;S.page='auth';}}catch{}render();

if(location.pathname==='/'&&location.hash==='#how')requestAnimationFrame(()=>document.getElementById('how')?.scrollIntoView());
